// Array entries allow the same French phrase to be listed alongside different contexts;
// the last definition wins, keeping translations predictable without duplicate object keys.
const english: Record<string, string> = Object.fromEntries(entries);
const frenchByEnglish = new Map<string, string>();
for (const [french, translated] of entries) {
  if (french !== translated && !frenchByEnglish.has(translated)) frenchByEnglish.set(translated, french);
}

export function isLocale(value: string | undefined): value is Locale {
  return value === "fr" || value === "en";
}

function translateDynamic(text: string): string | undefined {
  const match = (pattern: RegExp, render: (...values: string[]) => string) => {
    const result = pattern.exec(text);
    return result ? render(...result.slice(1)) : undefined;
  };
  const genreDescriptionPrefix = "Posséder tous les personnages actifs du genre ";
  const genreDescriptionSuffix = ", aux couleurs de son booster.";
  if (text.startsWith(genreDescriptionPrefix) && text.endsWith(genreDescriptionSuffix)) {
    const genre = text.slice(genreDescriptionPrefix.length, -genreDescriptionSuffix.length);
    return `Collect every active character in the ${english[genre] ?? genre} genre to earn its pack-colored frame.`;
  }

  return (
    match(/^Posséder (\d+) % des personnages$/, (percent) => `Collect ${percent}% of the characters`) ??
    match(/^Posséder (\d+) % des Légendaires actives$/, (percent) => `Collect ${percent}% of active Legendary cards`) ??
    match(/^Posséder (\d+) % des Mythiques actives$/, (percent) => `Collect ${percent}% of active Mythic cards`) ??
    match(/^Posséder (\d+) % de l'album pendant la saison$/, (percent) => `Collect ${percent}% of the album during the season`) ??
    match(/^Se connecter (.+) jours consécutifs$/, (days) => `Log in for ${days} consecutive days`) ??
    match(/^Ouvrir (.+) boosters$/, (count) => `Open ${count} packs`) ??
    match(/^Ouvre (.+) boosters$/, (count) => `Open ${count} packs`) ??
    match(/^Plus de (.+)$/, (count) => `More than ${count}`) ??
    match(/^Aucune vente sur les (.+) derniers jours\\.$/, (days) => `No sales in the past ${days} days.`) ??
    match(/^La cote de (.+)$/, (card) => `The market value of ${card}`) ??
    match(/^Il manque (\\d+) ◆$/, (amount) => `You are short ${amount} ◆`) ??
    match(/^Compter (\d+) parrainages payés$/, (count) => `Complete ${count} paid referrals`) ??
    match(/^Vendre (\d+) cartes sur le marché$/, (count) => `Sell ${count} cards on the marketplace`) ??
    match(/^Compte créé avant le (.+)$/, (date) => `Account created before ${date}`) ??
    match(/^Compte créé le (.+)$/, (date) => `Account created on ${date}`) ??
    match(/^Posséder 100 % d'une franchise d'au moins ([\d,.]+) personnages?$/, (count) => `Collect every character in a franchise with at least ${count} characters`) ??
    match(/^(\d[\d\s,.]*) \/ (\d[\d\s,.]*) personnages · (\d+) %$/, (current, total, percent) => `${current} / ${total} characters · ${percent}%`) ??
    match(/^(\d[\d\s,.]*) \/ (\d[\d\s,.]*) personnage · (\d+) %$/, (current, total, percent) => `${current} / ${total} character · ${percent}%`) ??
    match(/^(\d[\d\s,.]*) \/ (\d[\d\s,.]*) (légendaires|mythiques) · (\d+) %$/, (current, total, rarity, percent) => `${current} / ${total} ${rarity === "légendaires" ? "Legendary cards" : "Mythic cards"} · ${percent}%`) ??
    match(/^(\d[\d\s,.]*) \/ (\d[\d\s,.]*) jours$/, (current, total) => `${current} / ${total} days`) ??
    match(/^(\d[\d\s,.]*) \/ (\d[\d\s,.]*) boosters$/, (current, total) => `${current} / ${total} packs`) ??
    match(/^(\d[\d\s,.]*) \/ (\d[\d\s,.]*) parrainages payés$/, (current, total) => `${current} / ${total} paid referrals`) ??
    match(/^(\d[\d\s,.]*) \/ (\d[\d\s,.]*) ventes$/, (current, total) => `${current} / ${total} sales`) ??
    match(/^(\d[\d\s,.]*) \/ (\d[\d\s,.]*) · (.+)$/, (current, total, franchise) => `${current} / ${total} · ${franchise}`) ??
    match(/^Plus que (\d[\d\s,.]*) (.+)$/, (count, unit) => {
      const singular = Number(count.replace(/\s/g, "")) === 1;
      const translatedUnit = unit.startsWith("personnage") ? (singular ? "character" : "characters")
        : unit.startsWith("jour") ? (singular ? "day" : "days")
        : unit.startsWith("booster") ? (singular ? "pack" : "packs")
        : unit.startsWith("légendaire") ? (singular ? "Legendary card" : "Legendary cards")
        : unit.startsWith("mythique") ? (singular ? "Mythic card" : "Mythic cards")
        : unit.startsWith("parrainage") ? (singular ? "referral" : "referrals")
        : unit.startsWith("vente") ? (singular ? "sale" : "sales")
        : unit;
      return `Only ${count} ${translatedUnit}`;
    }) ??
    match(/^Maîtrise (.+)$/, (genre) => `Mastery: ${english[genre] ?? genre}`)
  );
}

export function translate(text: string, locale: Locale): string {
  if (locale === "fr") return frenchByEnglish.get(text) ?? text;
  const exact = english[text];
  if (exact !== undefined) return exact;
  // Translate trimmed DOM text while preserving JSX whitespace around it.
  const trimmed = text.trim();
  if (trimmed) {
    const translated = english[trimmed] ?? translateDynamic(trimmed);
    if (translated !== undefined) {
      const start = text.indexOf(trimmed);
      return `${text.slice(0, start)}${translated}${text.slice(start + trimmed.length)}`;
    }
  }
  return text;
}
